  ["19226412"] = {
    Content = "“在远方，或许有一家属于你自己的书店或是酒馆。”",
    ContentEN = "\"Somewhere out there, perhaps there's a bookshop, or a tavern... that's yours, and yours alone.\"",
    ContentFR = "« Au loin... peut-être existe-t-il un lieu qui n’appartient qu’à vous. Une librairie. Ou une taverne. »",
    ContentJP = "「遠方には、あなただけの書店や酒場が待っているかもしれません。」",
    ContentKR = "\"머나먼 곳 어딘가엔 오직 당신만을 위한 서점이나 술집이 있을지도 모릅니다.\"",
    ContentTC = "「在遠方，或許有一家屬於你自己的書店或是酒館。」",
    GUID = "19226412"
  },
  ["1922643C"] = {
    Content = "“远方，一个聚合了梦想、等待与不确定的词汇。“",
    ContentEN = "\"'Somewhere out there' — three little words that pack in dreams, longing, and surprise.\"",
    ContentFR = "« Au loin... un mot chargé de rêves, d’attente... et d’inconnu. »",
    ContentJP = "「遠方とは、夢と、約束と、少しの不安が混ざり合う場所。」",
    ContentKR = "\"머나먼 곳이란, 수많은 꿈과 기다림, 그리고 알 수 없는 내일로 이루어진 단어입니다.\"",
    ContentTC = "「遠方，一個聚合了夢想、等待與不確定的詞彙。「",
    GUID = "1922643C"
  },
  ["19226466"] = {
    Content = "“在远方，或许有你想念的人也在日夜等待着你的突然出现。”",
    ContentEN = "\"Somewhere out there, the person you miss most might be waiting... hoping you'll show up at their door one day.\"",
    ContentFR = "« Au loin, peut-être qu’une personne qui vous est chère attend, jour et nuit... que vous apparaissiez enfin. »",
    ContentJP = "「遠方には、あなたを想う誰かが、今日も静かに帰りを待っているかもしれません。」",
    ContentKR = "\"머나먼 곳에 당신의 깜짝방문을 밤낮으로 기다리는 누군가가 있을지도 모릅니다.\"",
    ContentTC = "「在遠方，或許有你想念的人也在日夜等待著你的突然出現。」",
    GUID = "19226466"
  },
  ["19226490"] = {
    Content = "“在远方，有着无数的未知，但一定和现在大不一样。”",
    ContentEN = "\"Somewhere out there is all unknowns... and it won't feel anything like here.\"",
    ContentFR = "« Au loin, tout est incertain... mais tout y sera différent. »",
    ContentJP = "「未知は尽きません。けれど、今とはまるで違う景色が、きっと広がっています。」",
    ContentKR = "\"머나먼 그곳에서 어떤 내일이 펼쳐질지는 알 수 없지만, 분명히 오늘과는 전혀 다를 겁니다.\"",
    ContentTC = "「在遠方，有著無數的未知，但一定和現在大不一樣。」",
    GUID = "19226490"
  },
  ["192264BA"] = {
