  B47EBAFC = {
    Content = "浮名洗尽始见心，风月不染本来明。",
    ContentEN = [[
Strip away the fleeting fame, and the true heart is revealed.
 Untouched by worldly dust, its original clarity remains.]],
    ContentFR = "Quand les faux-semblants s’effacent, le cœur véritable apparaît.\n Préservé de la poussière du monde, il demeure clair, tel qu’à l’origine.",
    ContentJP = "虚名捨ててようやく現れ、風月に染まず清らかな心。",
    ContentKR = "허명을 씻어내면 마음이 보이느니, 하늘의 달은 본래 티끌 없이 맑은 법.",
    ContentTC = "浮名洗盡始見心，風月不染本來明。",
    GUID = "B47EBAFC"
  },
  B47EBB26 = {
    Content = "远道而来的朋友，你拂开繁花，可曾窥见自己明朗的本心呢？",
    ContentEN = "Traveler from afar, as you brush aside the blossoms of your past, have you glimpsed your own bright and clear heart?",
    ContentFR = "{性别:Ami venu|Amie venue} de loin, en écartant les fleurs écloses, as-tu entrevu la limpidité de ton propre cœur ?",
    ContentJP = "遠路はるばる訪れた友よ、あなたまるで満開の花の如く、自らの澄みきった本来の心を垣間見ただろうか？",
    ContentKR = "멀리서 찾아온 친구! 화려한 치장을 걷어내면, 자신의 본심이 환하게 드러날 거야.",
    ContentTC = "遠道而來的朋友，你拂開繁花，可曾窺見自己明朗的本心呢？",
    GUID = "B47EBB26"
  },
