  B47ECB3A = {GUID = "B47ECB3A"},
  B47ECB64 = {
    Content = "好似做了个久远的美梦……",
    ContentEN = "Feels like I had a long, beautiful dream...",
    ContentFR = "On dirait que j’ai fait un rêve ancien... Un très beau rêve.",
    ContentJP = "美しく長い夢を見たようだ…",
